{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Haloperidol, a para-chlorophenyl drug with a basic amine, has absolute oral bioavailability of about 65-70% in humans, supporting high F for the query's chlorophenyl amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Procainamide, a para-substituted benzamide with a basic aminoethyl side chain closely analogous to the query, has absolute oral bioavailability of 81 ± 13%, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Molsidomine, a morpholine-containing drug, has absolute oral bioavailability of 44 ± 15%, supporting that morpholine-containing small molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Sematilide, a benzamide antiarrhythmic with a basic side chain, has absolute oral bioavailability around 46-59%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Indoramin has a median oral bioavailability of 23.6% (range 2.1-77.2%), just above the 20% threshold; this is supportive but weaker because of the wide range and borderline median.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Loperamide has very low oral bioavailability (0.3%) due to P-gp efflux and first-pass metabolism; this is contradictory, but its large lipophilic structure and P-gp liability transfer poorly to the small polar morpholinobenzamide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small para-chlorobenzamide with a morpholinoethyl side chain. Multiple close structural analogues—procainamide, sematilide, haloperidol, and morpholine-containing drugs—show absolute oral bioavailability well above 20%, often 44-90%. The main contradictory example, loperamide, has very low F but is structurally distant and its P-gp-mediated poor bioavailability is not expected to transfer. Under a modified-release formulation, the extent of absorption is unlikely to fall below 20% for this well-absorbed, low-molecular-weight amide.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query molecule itself under modified-release conditions.",
    "Retrieved analogues have modest Morgan similarity (0.28-0.34), so transferability is limited.",
    "Indoramin shows wide interindividual F range, illustrating first-pass variability for basic amine drugs."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

